-- Minimal schema contract inspected read-only from the connected project.
-- Auth/session helpers are local test substitutes; no accounts or secrets.
create schema auth;
create schema private;
create schema storage;
create role anon;
create role authenticated;
create type public.platform_key as enum ('all','web','android','ios');
create type public.access_state as enum ('enabled','readonly','disabled','locked');
create type public.permission_effect as enum ('allow','deny');
create type public.rule_scope as enum ('global','role','user');
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create table auth.users(id uuid primary key,email text,email_confirmed_at timestamptz,banned_until timestamptz);
create table public.roles(id uuid primary key default gen_random_uuid(),key text unique,name text,active boolean default true);
create table public.profiles(id uuid primary key references auth.users,role_id uuid references public.roles,email text,full_name text,status text default 'active');
create table public.system_modules(id uuid primary key default gen_random_uuid(),key text unique,is_active boolean default true);
create table public.permissions(id uuid primary key default gen_random_uuid(),key text unique,module_id uuid references public.system_modules,action text);
create table public.role_permissions(role_id uuid,permission_id uuid,effect public.permission_effect,primary key(role_id,permission_id));
create table public.user_permissions(user_id uuid,permission_id uuid,effect public.permission_effect,starts_at timestamptz,ends_at timestamptz,primary key(user_id,permission_id));
create table public.module_access_rules(module_id uuid,scope_type public.rule_scope,role_id uuid,user_id uuid,platform public.platform_key,access_state public.access_state,starts_at timestamptz,ends_at timestamptz,updated_at timestamptz default now());
create table public.system_lock_rules(scope text,platform public.platform_key,is_locked boolean,starts_at timestamptz,ends_at timestamptz);
create table public.crm_records(collection text,id text,data jsonb not null,primary key(collection,id));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_user_id uuid,action text,entity_type text,new_data jsonb,metadata jsonb);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text,updated_at timestamptz default now(),last_accessed_at timestamptz,version text default 'v1',archived_at timestamptz,is_delete_marker boolean default false);
-- Return tables exist today; the optional allocation column is added by the
-- prepared warehouse extension. Test both before and after that extension.
create table public.product_returns(id uuid primary key default gen_random_uuid(),return_number bigint generated by default as identity,status text default 'pending',workflow_status text,reason text,warehouse_id uuid,delivered_at timestamptz,inventory_posted_at timestamptz,updated_at timestamptz default now());
create table public.product_return_items(id uuid primary key default gen_random_uuid(),product_return_id uuid references public.product_returns on delete cascade,quantity numeric,usable_quantity numeric,damaged_quantity numeric);
create function private.current_role_key() returns text language sql stable security definer set search_path='' as $$
 select r.key from public.profiles p join public.roles r on r.id=p.role_id join auth.users u on u.id=p.id
 where p.id=auth.uid() and p.status='active' and r.active and coalesce(current_setting('test.revoked',true),'')<>'true' and (u.banned_until is null or u.banned_until<=now())
$$;
create function private.has_module_access(m text,a text,p public.platform_key) returns boolean language sql stable security definer set search_path='' as $$
 select private.current_role_key() is not null and coalesce((select up.effect='allow' from public.user_permissions up join public.permissions pe on pe.id=up.permission_id where up.user_id=auth.uid() and pe.key=m||'.'||a and (up.starts_at is null or up.starts_at<=now()) and (up.ends_at is null or up.ends_at>now())),(select rp.effect='allow' from public.role_permissions rp join public.permissions pe on pe.id=rp.permission_id join public.profiles pr on pr.role_id=rp.role_id where pr.id=auth.uid() and pe.key=m||'.'||a),false)
$$;
create function private.crm_upgrade_require(m text,a text,management boolean default true) returns uuid language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or not private.has_module_access(m,a,'web') or (management and private.current_role_key() not in ('super_admin','admin','manager')) then raise exception 'Permission denied' using errcode='42501'; end if;
 return auth.uid();
end $$;
grant usage on schema public,private,auth to authenticated;
grant execute on function auth.uid(),private.current_role_key(),private.has_module_access(text,text,public.platform_key),private.crm_upgrade_require(text,text,boolean) to authenticated;
-- Mirror the generic record API grants so tests can exercise direct tampering.
grant select,insert,update,delete on public.crm_records to authenticated;
